llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C62"],
      "claim": "In humans, trovafloxacin absolute oral bioavailability was 88% after a single 200 mg oral dose, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In healthy male subjects, ketanserin absolute oral bioavailability was 46.8 ± 8.2% after a 20-mg oral dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "In normal volunteers, propranolol absolute oral bioavailability was 18.9% ± 3.8% after a 20-mg oral dose, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transferability evidence molecules show absolute oral bioavailability values of 28–88%, clearly above the 20% threshold. The main contradictory evidence, propranolol at ~19%, is a high-scoring molecule but has dose-dependent and conflicting records. Overall, high bioavailability is better supported.",
  "evidence_gaps": [
    "Propranolol evidence is conflicting and dose-dependent: its strongest absolute record is below 20%, but other absolute/systemic records are above 20%, adding uncertainty.",
    "Some records used unspecified bioavailability types or altered conditions such as cirrhosis, ER formulations, or fasting states and were discounted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

